package com.rubidiumclient.module.combatimport com.rubidiumclient.core.proxy.EntityTrackerimport com.rubidiumclient.core.relay.RubidiumRelaySessionimport com.rubidiumclient.events.PacketEventimport com.rubidiumclient.events.PacketEventBusimport com.rubidiumclient.module.*import com.rubidiumclient.utils.InventoryUtilimport com.rubidiumclient.utils.MathUtilimport com.rubidiumclient.utils.PacketUtilimport com.rubidiumclient.utils.PlacementUtilimport com.rubidiumclient.utils.WorldBlockTrackerimport kotlinx.coroutines.*import org.cloudburstmc.math.vector.Vector3fimport org.cloudburstmc.math.vector.Vector3iimport org.cloudburstmc.protocol.bedrock.data.LevelEventimport org.cloudburstmc.protocol.bedrock.packet.AddEntityPacketimport org.cloudburstmc.protocol.bedrock.packet.LevelEventPacketimport kotlin.math.floorclass CrystalAura : BaseModule(    name        = "CrystalAura",    category    = ModuleCategory.COMBAT,    description = "Hasar simülasyonuna göre en iyi noktaya kristal yerleştirir/kırar") {    companion object {        private const val EXPLOSION_SIZE   = 6f        private const val TICK_INTERVAL_MS = 50L        private val NON_SOLID = setOf(            "minecraft:air", "minecraft:water", "minecraft:flowing_water",            "minecraft:lava", "minecraft:flowing_lava",            "minecraft:void_air", "minecraft:cave_air"        )    }    private val range           = float("Range",           5f,   3f,  10f)    private val suicide         = bool ("Suicide",         false)    private val place           = bool ("Place",           true)    private val placeCount      = int  ("PlaceCount",      4,    1,   8)    private val placeDelayMs    = int  ("PlaceDelay",      100,  50,  500)    private val explodeDelayMs  = int  ("ExplodeDelay",    50,   20,  300)    private val removeParticles = bool ("RemoveParticles", true)    @Volatile private var lastExplodeMs = 0L    @Volatile private var lastPlaceMs   = 0L    @Volatile private var cacheWarmed   = false    @Volatile private var tickJob: Job? = null    private data class ExplosionResult(val mostDamage: Float, val selfDamage: Float)    override fun onEnable() {        super.onEnable()        lastExplodeMs = 0L        lastPlaceMs   = 0L        cacheWarmed   = false        PacketEventBus.register(this)        tickJob = scope.launch { tickLoop() }    }    override fun onDisable() {        tickJob?.cancel()        PacketEventBus.unregister(this)        super.onDisable()    }    override fun onPacket(event: PacketEvent) {        if (!isEnabled) return        when (val pkt = event.packet) {            is AddEntityPacket -> {                if (!pkt.identifier.contains("crystal", ignoreCase = true)) return                val now = System.currentTimeMillis()                if (now - lastExplodeMs < explodeDelayMs.value) return                val cx = pkt.position.x; val cy = pkt.position.y; val cz = pkt.position.z                if (MathUtil.dist3(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ) > range.value) return                val dmg = simulateExplosionDamage(cx, cy, cz)                if (dmg.selfDamage <= dmg.mostDamage || suicide.value) {                    val session = PacketEventBus.currentSession ?: return                    explodeCrystal(session, pkt.runtimeEntityId)                    lastExplodeMs = now                }            }            is LevelEventPacket -> {                if (removeParticles.value && pkt.type == LevelEvent.PARTICLE_EXPLOSION) event.cancel()            }            else -> {}        }    }    private suspend fun tickLoop() {        while (currentCoroutineContext().isActive) {            if (isEnabled) tick()            delay(TICK_INTERVAL_MS)        }    }    private fun tick() {        val session = PacketEventBus.currentSession ?: return        if (!cacheWarmed) {            PlacementUtil.getBlockDefinition(session, "minecraft:obsidian")            cacheWarmed = true        }        val now = System.currentTimeMillis()        if (now - lastExplodeMs >= explodeDelayMs.value) tryExplodeBest(session, now)        if (place.value && now - lastPlaceMs >= placeDelayMs.value) tryPlaceBest(session, now)    }    private fun tryExplodeBest(session: RubidiumRelaySession, now: Long) {        val crystals = EntityTracker.getCrystals(range.value)        if (crystals.isEmpty()) return        var bestId: Long? = null        var bestDamage = -1f        for (c in crystals) {            val dmg = simulateExplosionDamage(c.x, c.y, c.z)            val effective = if (dmg.selfDamage > dmg.mostDamage && !suicide.value) -1f else dmg.mostDamage            if (effective > bestDamage) {                bestDamage = effective                bestId = c.runtimeId            }        }        if (bestId != null && bestDamage > 0f) {            explodeCrystal(session, bestId)            lastExplodeMs = now        }    }    private fun tryPlaceBest(session: RubidiumRelaySession, now: Long) {        val bases = searchPlaceBase().toMutableList()        if (bases.isEmpty()) return        val prepared = PlacementUtil.prepareItemForUse(session, "minecraft:end_crystal") ?: return        var placed = 0        for ((x, y, z) in bases) {            if (placed >= placeCount.value) break            val dmg = simulateExplosionDamage(x + 0.5f, y + 1.5f, z + 0.5f)            if (dmg.mostDamage <= 0f) continue            val blockPos = Vector3i.from(x, y + 1, z)            val blockId = WorldBlockTracker.getBlockIdentifier(x, y, z) ?: "minecraft:obsidian"            val ok = PlacementUtil.sendPlacementUseRaw(                session = session,                prepared = prepared,                blockPos = blockPos,                blockId = blockId,                clickPosition = Vector3f.from(0.5f, 0.5f, 0.5f)            )            if (ok) placed++        }        PlacementUtil.revert(session, prepared)        if (placed > 0) lastPlaceMs = now    }    private fun searchPlaceBase(): List<Triple<Int, Int, Int>> {        if (!WorldBlockTracker.hasAnyTerrainData()) return emptyList()        val r  = floor(range.value).toInt()        val cx = floor(EntityTracker.selfX).toInt()        val cy = floor(EntityTracker.selfY).toInt()        val cz = floor(EntityTracker.selfZ).toInt()        val bases = ArrayList<Triple<Int, Int, Int>>()        for (x in cx - r..cx + r) {            for (y in cy - r..cy + r) {                for (z in cz - r..cz + r) {                    val id = WorldBlockTracker.getBlockIdentifier(x, y, z) ?: continue                    if (id != "minecraft:obsidian" && id != "minecraft:bedrock") continue                    val above = WorldBlockTracker.getBlockIdentifier(x, y + 1, z)                    if (above != null && above !in NON_SOLID) continue                    bases.add(Triple(x, y, z))                }            }        }        return bases    }    private fun simulateExplosionDamage(cx: Float, cy: Float, cz: Float): ExplosionResult {        val diameter = EXPLOSION_SIZE * 2f        var selfDamage = 0f        var mostDamage = 0f        val selfDist = MathUtil.dist3(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY + 0.9f, EntityTracker.selfZ)        if (selfDist <= diameter) {            val exposure = exposureTo(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ)            selfDamage = explosionDamage(selfDist, diameter, exposure)        }        for (p in EntityTracker.getPlayers(diameter)) {            if (p.runtimeId == EntityTracker.selfRuntimeId) continue            val dist = MathUtil.dist3(cx, cy, cz, p.x, p.y + 0.9f, p.z)            if (dist > diameter) continue            val exposure = exposureTo(cx, cy, cz, p.x, p.y, p.z)            val dmg = explosionDamage(dist, diameter, exposure)            if (dmg > mostDamage) mostDamage = dmg        }        return ExplosionResult(mostDamage, selfDamage)    }    private fun explosionDamage(distance: Float, diameter: Float, exposure: Float): Float {        if (distance > diameter) return 0f        val impact = (1f - distance / diameter) * exposure        return (impact * impact + impact) / 2f * 7f * diameter + 1f    }    private fun exposureTo(cx: Float, cy: Float, cz: Float, tx: Float, ty: Float, tz: Float): Float {        if (!WorldBlockTracker.hasAnyTerrainData()) return 1f        val samples = arrayOf(            Triple(tx, ty + 0.1f, tz),            Triple(tx, ty + 0.9f, tz),            Triple(tx, ty + 1.6f, tz),            Triple(tx + 0.3f, ty + 0.9f, tz),            Triple(tx - 0.3f, ty + 0.9f, tz)        )        var clear = 0        for ((sx, sy, sz) in samples) {            if (!isRayBlocked(cx, cy, cz, sx, sy, sz)) clear++        }        return clear.toFloat() / samples.size    }    private fun isRayBlocked(x0: Float, y0: Float, z0: Float, x1: Float, y1: Float, z1: Float): Boolean {        val dist = MathUtil.dist3(x0, y0, z0, x1, y1, z1)        if (dist < 0.01f) return false        val steps = (dist * 2f).toInt().coerceIn(1, 40)        for (i in 1 until steps) {            val t = i.toFloat() / steps            val bx = floor(x0 + (x1 - x0) * t).toInt()            val by = floor(y0 + (y1 - y0) * t).toInt()            val bz = floor(z0 + (z1 - z0) * t).toInt()            val id = WorldBlockTracker.getBlockIdentifier(bx, by, bz) ?: continue            if (id !in NON_SOLID) return true        }        return false    }    private fun explodeCrystal(session: RubidiumRelaySession, runtimeId: Long) {        PacketUtil.sendSwing(session)        PacketUtil.sendAttack(session, runtimeId)    }}